    setPairError(PhoneModel.pairLockedText());
    return;
  }
  if (error === "bad_code") {
    setPairError(PhoneModel.pairWrongText((body || {}).remaining_attempts));
    return;
  }
  setPairError("配对失败：" + String((body && (body.text || body.error)) || status));
}

